% Parenthesized footnote numbers reproduce the printed article.
\makeatletter
\renewcommand{\@makefnmark}{\hbox{\normalfont(\textsuperscript{\normalfont\@thefnmark})}}
\renewcommand{\@makefntext}[1]{\parindent 1em\noindent\hb@xt@1.8em{\hss\@makefnmark}\,#1}
\makeatother

